const brl = n => 'R$ ' + Number(n).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const pad = n => String(n).padStart(2, '0');
const brt = d => new Date(new Date(d).getTime() - 3 * 3600 * 1000); // America/Sao_Paulo (UTC-3, sem horario de verao)
const dataBR = d => { const x = brt(d); return pad(x.getUTCDate()) + '/' + pad(x.getUTCMonth() + 1) + '/' + x.getUTCFullYear(); };
const horaBR = d => { const x = brt(d); return pad(x.getUTCHours()) + ':' + pad(x.getUTCMinutes()); };

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const amanha = dataBR(Date.now() + 24 * 3600 * 1000);
const instalacoes = rows.map(r => ({
  pedido_numero: r.numero,
  horario: horaBR(r.data_instalacao),
  cliente_nome: r.cliente_nome,
  cliente_telefone: r.cliente_telefone,
  endereco: r.cliente_endereco || 'Endereço não informado',
  tecnico: r.tecnico_nome || 'Sem técnico',
  valor_total: Number(r.valor_total)
}));
const mensagem = instalacoes.length === 0
  ? 'Nenhuma instalação agendada para ' + amanha + '.'
  : 'Instalações de ' + amanha + ' (' + instalacoes.length + '):\n' +
    instalacoes.map(i => '- ' + i.horario + ' | ' + i.cliente_nome + ' | ' + i.endereco + ' | Técnico: ' + i.tecnico).join('\n');
return [{ json: { payload: {
  evento: 'resumo_instalacoes_amanha',
  data_referencia: amanha,
  total_instalacoes: instalacoes.length,
  instalacoes,
  mensagem
}}}];
